<?php $pageTitle='Add Grease Trap';require 'includes/header.php';$errors=[];$v=['trap_code'=>'','location'=>'','last_cleaned_date'=>date('Y-m-d'),'cleaning_interval'=>'30'];
if($_SERVER['REQUEST_METHOD']==='POST'){$v['trap_code']=trim($_POST['trap_code']??'');$v['location']=trim($_POST['location']??'');$v['last_cleaned_date']=$_POST['last_cleaned_date']??'';$v['cleaning_interval']=$_POST['cleaning_interval']??'';
if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))$errors[]='Invalid form submission.';if($v['trap_code']==='')$errors[]='Trap code is required.';if($v['location']==='')$errors[]='Location is required.';if($v['last_cleaned_date']==='')$errors[]='Last cleaned date is required.';if(!ctype_digit((string)$v['cleaning_interval'])||(int)$v['cleaning_interval']<1)$errors[]='Cleaning interval must be positive.';
if(!$errors){$q=$pdo->prepare("SELECT COUNT(*) FROM grease_traps WHERE trap_code=?");$q->execute([$v['trap_code']]);if($q->fetchColumn())$errors[]='Trap code already exists.';}
if(!$errors){$q=$pdo->prepare("INSERT INTO grease_traps(trap_code,location,last_cleaned_date,cleaning_interval) VALUES(?,?,?,?)");$q->execute([$v['trap_code'],$v['location'],$v['last_cleaned_date'],(int)$v['cleaning_interval']]);flash('success','Grease trap added successfully.');header('Location: traps.php');exit;}}
?>
<section class="form-panel"><h3>Add Grease Trap</h3><p>Register a new grease trap.</p><?php if($errors):?><div class="errors"><?php foreach($errors as $e):?><div><?=h($e)?></div><?php endforeach;?></div><?php endif;?>
<form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><label>Trap Code<input name="trap_code" required value="<?=h($v['trap_code'])?>" placeholder="GT-006"></label><label>Location<input name="location" required value="<?=h($v['location'])?>"></label><label>Last Cleaned Date<input type="date" name="last_cleaned_date" required value="<?=h($v['last_cleaned_date'])?>"></label><label>Cleaning Interval (days)<input type="number" name="cleaning_interval" min="1" required value="<?=h($v['cleaning_interval'])?>"></label><div class="actions"><a class="btn secondary" href="traps.php">Cancel</a><button class="btn primary">Save Grease Trap</button></div></form></section><?php require 'includes/footer.php';?>